import React, { useRef, useEffect, useState } from "react";
import * as ort from "onnxruntime-web";

const classNames = ['BLOCK', 'INNER', 'OK', 'OUTER', 'SCAR', 'TEAR'];
const MODEL_INPUT_SIZE = 320;  // smaller for speed; change back if needed

function App() {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const [session, setSession] = useState(null);
  const inputNameRef = useRef(null);

  useEffect(() => {
    // Load ONNX model
    ort.InferenceSession.create("best.onnx").then(sess => {
      setSession(sess);
      inputNameRef.current = sess.inputNames[0];  // get input name dynamically
      console.log("ONNX input name:", inputNameRef.current);
    });

    // Get user video
    navigator.mediaDevices.getUserMedia({ video: true }).then(stream => {
      if (videoRef.current) videoRef.current.srcObject = stream;
    });
  }, []);

  useEffect(() => {
    if (!session) return;

    let canceled = false;

    async function runInferenceLoop() {
      while (!canceled) {
        await detectFrame();
        await new Promise(r => setTimeout(r, 50));  // small delay, adjust if needed
      }
    }

    runInferenceLoop();

    return () => { canceled = true; };
  }, [session]);

  async function detectFrame() {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    if (video.readyState !== HTMLMediaElement.HAVE_ENOUGH_DATA) return;

    const ctx = canvas.getContext("2d");
    canvas.width = MODEL_INPUT_SIZE;
    canvas.height = MODEL_INPUT_SIZE;

    // Draw video frame to canvas and get pixels
    ctx.drawImage(video, 0, 0, MODEL_INPUT_SIZE, MODEL_INPUT_SIZE);
    const imageData = ctx.getImageData(0, 0, MODEL_INPUT_SIZE, MODEL_INPUT_SIZE);

    // Preprocess: normalize and reorder channels to [1,3,H,W]
    const input = new Float32Array(3 * MODEL_INPUT_SIZE * MODEL_INPUT_SIZE);
    for (let i = 0; i < imageData.data.length; i += 4) {
      const idx = i / 4;
      input[idx] = imageData.data[i] / 255.0; // R
      input[idx + MODEL_INPUT_SIZE ** 2] = imageData.data[i + 1] / 255.0; // G
      input[idx + 2 * MODEL_INPUT_SIZE ** 2] = imageData.data[i + 2] / 255.0; // B
    }

    const tensor = new ort.Tensor("float32", input, [1, 3, MODEL_INPUT_SIZE, MODEL_INPUT_SIZE]);
    const feeds = { [inputNameRef.current]: tensor };

    try {
      const output = await session.run(feeds);
      const outputTensor = Object.values(output)[0];
      const boxes = parseYOLOv5Output(outputTensor.data, outputTensor.dims);
      drawBoxes(boxes);
    } catch (err) {
      console.error("Inference failed:", err);
    }
  }

  function parseYOLOv5Output(data, dims) {
    // dims: [batch, num_boxes, num_attrs]
    const [batch, num_boxes, num_attrs] = dims;
    const boxes = [];

    for (let i = 0; i < num_boxes; i++) {
      const offset = i * num_attrs;
      const slice = data.slice(offset, offset + num_attrs);
      const [x, y, w, h, conf, ...classConfs] = slice;
      const classId = classConfs.indexOf(Math.max(...classConfs));
      const classConf = classConfs[classId];

      if (conf * classConf > 0.4) {
        boxes.push({
          x: x - w / 2,
          y: y - h / 2,
          w,
          h,
          label: classNames[classId],
          confidence: conf * classConf,
        });
      }
    }

    return boxes;
  }

  function drawBoxes(boxes) {
    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video) return;

    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, MODEL_INPUT_SIZE, MODEL_INPUT_SIZE);
    ctx.drawImage(video, 0, 0, MODEL_INPUT_SIZE, MODEL_INPUT_SIZE);

    ctx.strokeStyle = "red";
    ctx.lineWidth = 2;
    ctx.font = "14px Arial";
    ctx.fillStyle = "red";

    for (const box of boxes) {
      ctx.strokeRect(box.x, box.y, box.w, box.h);
      ctx.fillText(`${box.label} (${(box.confidence * 100).toFixed(1)}%)`, box.x, box.y - 4);
    }
  }

  return (
    <div>
      <video ref={videoRef} autoPlay muted style={{ display: "none" }} />
      <canvas ref={canvasRef} style={{ border: "1px solid #333" }} />
    </div>
  );
}

export default App;
